const input = $json.body ?? $json;
const rawPayload = input.raw_payload ?? {};
const raw = typeof rawPayload === 'string' ? JSON.parse(rawPayload) : rawPayload;
const apiKeyId = input.api_key_id ?? raw.api_key_id;
const clientIp = input.client_ip;
if (!apiKeyId) throw new Error('api_key_id is required');
if (!clientIp) throw new Error('client_ip is required');
return [{ json: {
  event_type: input.event_type ?? 'api_key_compromised',
  api_key_id: apiKeyId,
  client_ip: clientIp,
  detection_reason: input.detection_reason ?? raw.detection_reason ?? 'not_allowed_ip',
  incident_id: input.incident_id ?? raw.incident_id ?? null,
  timestamp: input.timestamp ?? new Date().toISOString()
} }];

