={{ (() => {
  const response = $json;
  const incident = response.incident ?? {};
  const detection = $('Normalize Detection Event').item.json;
  const reason = incident.detection_reason ?? incident.reason ?? detection.detection_reason ?? 'unknown';
  const reasons = { not_allowed_ip: '비허용 IP에서 API 키 사용', suspicious_user_agent: '의심스러운 User-Agent에서 API 키 사용' };
  const incidentId = incident.incident_id ?? response.incident_id;
  const incidentState = incidentId ? (incident.status === 'created' ? '생성 완료' : '생성 확인') : '미생성';
  const revoked = response.key_revoked === true;
  const replaced = Boolean(response.new_api_key_id);
  const blocked = response.ip_blocked === true || incident.ip_blocked === true;
  return '🚨 [시나리오 3 API 키 유출 의심]\n'
    + '키 식별자: ' + String(incident.api_key_id ?? detection.api_key_id ?? '확인 불가')
    + ' | 공격 IP: ' + String(incident.client_ip ?? detection.client_ip ?? '확인 불가')
    + '\n탐지 사유: ' + String(reasons[reason] ?? reason)
    + '\n📋 인시던트: ' + String(incidentId ?? '없음') + ' | 생성 상태: ' + incidentState
    + '\n대응 결과: 기존 키 폐기 ' + (revoked ? '완료' : '미확인')
    + ' · 교체 키 발급 ' + (replaced ? '확인' : '미확인')
    + ' · IP 차단 ' + (blocked ? '완료' : '미확인');
})() }}
